  const rounds: Array<UsageMetadata | undefined> = [
    undefined,
    {inputTokens: 2, outputTokens: 3, totalTokens: 5},
    undefined,
    {inputTokens: 7, outputTokens: 11, totalTokens: 18},
    undefined,
  ];

  expect(rounds.reduce(accumulateUsage, undefined)).toEqual({inputTokens: 9, outputTokens: 14, totalTokens: 23});
  expect([undefined, undefined].reduce(accumulateUsage, undefined)).toBeUndefined();
});
